/**
 * PdfFonts — B Titr 2.01 for PdfBuilder (jsPDF virtual file system)
 * ==========================================================================
 *
 * Usage (load after jsPDF, before building):
 *     <script src="pdf-font-b-titr.js"></script>
 *     PdfBuilder.create().registerFonts(PdfFonts).setFonts({ bidi: 'B Titr' })
 * Every pdf-font-*.js file adds one family to the global `PdfFonts`, so an
 * app loads only the families it uses; registerFonts(PdfFonts) registers all
 * loaded ones. Only the styles actually drawn are embedded in the PDF, each as
 * a subset of the glyphs used (PdfBuilder creates jsPDF with putOnlyUsedFonts).
 *
 * Format: PdfFonts.btitr = { family, version, styles: { normal, bold, italic,
 *         bolditalic: { vfsName, data (base64 TTF) } } }
 *
 * ─────────────────────────────────────────────────────────────────────────
 * FONT
 * ─────────────────────────────────────────────────────────────────────────
 *
 * B Titr 2.01
 * Source: https://www.bornaray.com/ (https://www.bornaray.com/Content/downloads/fonts/BTITRBD.rar)
 *
 * normal / bold : the same file, BTITRBD.TTF — B Titr has a single (bold) weight.
 * italic / bold italic : generated by slanting the outlines 10° (oblique) with
 *     fontTools, because B Titr has no italic.
 * Coverage: Arabic and Persian letters with their presentation forms, digits and
 *     basic punctuation. NO Latin letters and no ? ; " @ # and similar signs —
 *     the PdfBuilder fallback fonts draw them.
 * ASCII digits 0–9 map to the same glyphs as Persian digits, so they are drawn
 *     with Persian shapes; the text (and copy/paste) keeps the ASCII digits.
 * Windows: the font declares only the Arabic code page (charset 178).
 *
 * ─────────────────────────────────────────────────────────────────────────
 * LICENSE
 * ─────────────────────────────────────────────────────────────────────────
 *
 * (c) 2000 Borna Rayaneh (https://www.bornaray.com/)
 *
 * No license file is published with these fonts. They are downloadable from
 * Borna Rayaneh's website, https://www.bornaray.com/; the files were obtained unmodified
 * from https://www.bornaray.com/Content/downloads/fonts/BTITRBD.rar. All rights,
 * including the right to grant a license for use, embedding or redistribution,
 * belong to Borna Rayaneh. The font files set no embedding restriction (OS/2
 * fsType 0). NOTICE.txt, in this folder, must travel with this file.
 */
(function (global) {
    'use strict';
    var PdfFonts = global.PdfFonts = global.PdfFonts || {};
    PdfFonts.btitr = {
        family: 'B Titr',
        version: '2.01',
        styles: {
            normal:     { vfsName: 'BTitr-Regular.ttf',    data: '' },
            bold:       { vfsName: 'BTitr-Bold.ttf',       data: '' },
            italic:     { vfsName: 'BTitr-Italic.ttf',     data: '' },
            bolditalic: { vfsName: 'BTitr-BoldItalic.ttf', data: '' }
        }
    };
    if (typeof module !== 'undefined' && module.exports) module.exports = PdfFonts;
})(typeof window !== 'undefined' ? window : this);
